const e=React.createElement;
function Impact(){const items=[['Wildlife','Recovery needs space, diagnosis, appropriate care and a credible route to release.'],['People','Environmental learning works when people can connect knowledge to places, livelihoods and decisions.'],['Systems','Field priorities travel further when they can reach institutions, finance and policy processes.']];const[i,setI]=useState(0);const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const style=useSpring({opacity:1,transform:'translateY(0px)',from:{opacity:0,transform:'translateY(12px)'},reset:true,immediate:reduce,config:{tension:210,friction:24},key:i});return e('div',{className:'impact-island'},e('div',{className:'chip-row',role:'group','aria-label':'Explore our work areas'},items.map((x,n)=>e('button',{key:x[0],type:'button',onClick:()=>setI(n),'aria-pressed':n===i,className:'chip '+(n===i?'is-active':'')},x[0]))),e(animated.div,{style,className:'impact-panel','aria-live':'polite'},e('strong',null,items[i][0]),e('p',null,items[i][1])))}
